static int rtl8156_disable(struct r8152 *tp)
{
	int ret, err = 0;

	ret = ocp_write_word(tp, MCU_TYPE_PLA, PLA_RX_FIFO_FULL, 0);
	if (ret < 0)
		err = ret;
	ret = ocp_write_word(tp, MCU_TYPE_PLA, PLA_RX_FIFO_EMPTY, 0);
	if (ret < 0)
		err = ret;

	ret = rtl8153_disable(tp);

	if (err < 0)
		return err;
	else
		return ret;
}
